            "type": "integer",
            "default": 0,
            "minimum": 0,
            "maximum": 4294967295
        },
        "max_value": {
            "type": "integer",
            "default": 0,
            "minimum": 0,
            "maximum": 4294967295
        },
        "decimals": {
            "type": "integer",
            "default": 0,
            "minimum": 0,
            "maximum": 6,
            "description": "Number of decimal places to allow. A \"0\" denotes this number field will require an integer."
        }
    },
    "required": [
        "_schema",
        "name"
    ],
    "additionalProperties": false
}

