            "type": "object",
            "description": "Hardware features required by the chute when assigning a physical interface",
            "properties": {
                "hwmode": {
                    "type": "string",
                    "description": "Required operating mode (11b for old hardware, 11g for 2.4 GHz, 11a for 5 GHz)",
                    "enum": [
                        "11b",
                        "11g",
                        "11a"
                    ]
                }
            }
        }
    },
    "required": [
        "type",
        "intfName"
    ]
