            "allowAdditionalProperties": false,
            "required": [
                "actionName",
                "availableToInternals",
                "availableToExternals",
                "mayRequireSetupFlag"
            ]
        }
    },
    "type": "array",
    "items": {
        "$ref": "#/definitions/possibleAction"
    }
}

