            "_format": "date",
            "type": "string"
        },
        "sample_date": {
            "_format": "date",
            "type": "string"
        },
        "source_jurisdiction": {
            "description": "Jurisdiction of the source of the data",
            "type": "string"
        }
    },
    "required": [
