            "type": "string",
            "pattern": "^\\d+$"
        },
        "yearList": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "fall": {
                        "$ref": "#/definitions/semester"
                    },
                    "winter": {
                        "$ref": "#/definitions/semester"
                    },
                    "summer": {
                        "$ref": "#/definitions/semester"
                    }
                },
                "required": [
                    "fall",
                    "winter",
                    "summer"
                ],
                "additionalProperties": false
            },
            "minItems": 3
        }
    },
    "required": [
        "sequenceInfo",
        "sourceUrl",
        "minTotalCredits",
        "yearList"
    ],
    "additionalProperties": false,
    "definitions": {
        "semester": {
            "type": "object",
            "properties": {
                "courseList": {
                    "type": "array",
                    "items": {
                        "oneOf": [
                            {
                                "$ref": "#/definitions/regularCourse"
                            },
                            {
                                "$ref": "#/definitions/electiveCourse"
                            },
                            {
                                "$ref": "#/definitions/orList"
                            }
                        ]
                    }
                },
                "isWorkTerm": {
                    "type": "string",
                    "enum": [
                        "true",
                        "false"
                    ]
                }
            },
            "required": [
                "courseList",
                "isWorkTerm"
            ],
            "additionalProperties": false
        },
        "orList": {
            "description": "A list of courses where the student can choose any one of them to add to take in the current semester",
            "type": "array",
            "items": {
                "oneOf": [
                    {
                        "$ref": "#/definitions/regularCourse"
                    },
                    {
                        "$ref": "#/definitions/electiveCourse"
                    }
                ]
            },
            "minItems": 2
        },
        "regularCourse": {
            "type": "object",
            "properties": {
                "code": {
                    "type": "string",
                    "pattern": "^\\w{4}\\s{1}\\d{3}$"
                },
                "isElective": {
                    "type": "string",
                    "pattern": "^false$"
                },
                "electiveType": {
                    "type": "string",
                    "pattern": "^$"
                }
            },
            "required": [
                "code",
                "isElective",
                "electiveType"
            ],
            "additionalProperties": false
        },
        "electiveCourse": {
            "type": "object",
            "properties": {
                "code": {
                    "type": "string",
                    "pattern": "^$"
                },
                "isElective": {
                    "type": "string",
                    "pattern": "^true$"
                },
                "electiveType": {
                    "type": "string",
                    "enum": [
                        "Science",
                        "Program",
                        "General"
                    ]
                }
            },
            "required": [
                "code",
                "isElective",
                "electiveType"
            ],
            "additionalProperties": false
        }
    }
}

{
    "type": "object",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "properties": {
        "total": {
            "$id": "/properties/total",
            "type": "object",
            "description": "Total income source amounts",
            "properties": {
                "income": {
                    "$id": "/properties/total/properties/income",
                    "description": "The total income for the income source. The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Income",
                    "multipleOf": 0.01,
                    "example": "500.25"
                },
                "expenses": {
                    "$id": "/properties/total/properties/expenses",
                    "description": "The total expenses for the income source. The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Expenses",
                    "example": "500.25"
                },
                "additions": {
                    "$id": "/properties/total/properties/additions",
                    "description": "The total additions to net profit (or deductions from net loss). The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Additions",
                    "multipleOf": 0.01,
                    "example": "500.25"
                },
                "deductions": {
                    "$id": "/properties/total/properties/deductions",
                    "description": "The total deductions from net loss (or additions to net profit). The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Deductions",
                    "multipleOf": 0.01,
                    "example": "500.25"
                }
            },
            "required": [
                "income",
                "expenses"
            ],
            "additionalProperties": false
        },
        "accountingAdjustments": {
            "$id": "/properties/accountingAdjustments",
            "description": "Further tax adjustments. The value must be between -99999999999999.98 and 99999999999999.98.",
            "type": "number",
            "title": "Accounting Adjustments",
            "multipleOf": 0.01,
            "example": "500.25"
        },
        "profit": {
            "$id": "/properties/profit",
            "description": "Income source profit",
            "type": "object",
            "properties": {
                "net": {
                    "$id": "/properties/profit/properties/net",
                    "description": "The net profit of the income source. The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Net",
                    "multipleOf": 0.01,
                    "example": "500.25"
                },
                "taxable": {
                    "$id": "/properties/profit/properties/taxable",
                    "description": "The taxable net profit of the income source. The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Taxable",
                    "multipleOf": 0.01,
                    "example": "500.25"
                }
            },
            "required": [
                "net",
                "taxable"
            ],
            "additionalProperties": false
        },
        "loss": {
            "$id": "/properties/loss",
            "description": "Income source loss",
            "type": "object",
            "properties": {
                "net": {
                    "$id": "/properties/loss/properties/net",
                    "description": "The net loss of the income source. The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Net",
                    "multipleOf": 0.01,
                    "example": "500.25"
                },
                "taxable": {
                    "$id": "/properties/loss/properties/taxable",
                    "description": "The taxable net loss of the income source. The value must be between 0.00 and 99999999999999.98.",
                    "type": "number",
                    "title": "Taxable",
                    "multipleOf": 0.01,
                    "example": "500.25"
                }
            },
            "required": [
                "net",
                "taxable"
            ],
            "additionalProperties": false
        }
    },
    "required": [
        "total",
        "profit",
        "loss"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Coverage object",
    "description": "Component of OGC Coverage Implementation Schema 1.1. Last updated: 2016-may-18. Copyright (c) 2016 Open Geospatial Consortium, Inc. All Rights Reserved. To obtain additional rights of use, visit http://www.opengeospatial.org/legal/.",
    "type": "object",
    "oneOf": [
        {
            "required": [
                "type",
                "domainSet",
                "rangeSet",
                "rangeType"
            ],
            "properties": {
                "id": {
                    "type": "string"
                },
                "type": {
                    "enum": [
                        "CoverageByDomainAndRangeType"
                    ]
                },
                "envelope": {
                    "$ref": "#/definitions/envelope"
                },
                "domainSet": {
                    "$ref": "#/definitions/domainSet"
                },
                "rangeSet": {
                    "$ref": "#/definitions/rangeSet"
                },
                "rangeType": {
                    "$ref": "#/definitions/rangeType"
                },
                "metadata": {
                    "$ref": "#/definitions/metadata"
                }
            }
        },
        {
            "required": [
                "type",
                "partitionSet",
                "rangeType"
            ],
            "properties": {
                "id": {
                    "type": "string"
                },
                "type": {
                    "enum": [
                        "CoverageByPartitioningType"
                    ]
                },
                "envelope": {
                    "$ref": "#/definitions/envelope"
                },
                "partitionSet": {
                    "$ref": "#/definitions/partitionSet"
                },
                "rangeType": {
                    "$ref": "#/definitions/rangeType"
                },
                "metadata": {
                    "$ref": "#/definitions/metadata"
                }
            }
        }
    ],
    "definitions": {
        "envelope": {
            "title": "envelope",
            "description": "The envelope around a coverage is defined by the lower and upper bound of each axis, respectively. The purpose of the axisLabels attribute, which lists the axis labels of all axisExtent elements in proper sequence, is to enforce axis sequence also in XML systems which do not preserve document order.",
            "type": "object",
            "required": [
                "type",
                "srsName",
                "axisLabels",
                "axis"
            ],
            "properties": {
                "type": {
                    "enum": [
                        "EnvelopeByAxisType"
                    ]
                },
                "id": {
                    "type": "string"
                },
                "srsName": {
                    "type": "string",
                    "format": "uri"
                },
                "axisLabels": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "axis": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "required": [
                            "type",
                            "lowerBound",
                            "upperBound",
                            "uomLabel"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "type": {
                                "enum": [
                                    "AxisExtentType"
                                ]
                            },
                            "id": {
                                "type": "string"
                            },
                            "axisLabel": {
                                "type": "string"
                            },
                            "lowerBound": {
                                "type": [
                                    "number",
                                    "string",
                                    "null",
                                    "boolean"
                                ]
                            },
                            "upperBound": {
                                "type": [
                                    "number",
                                    "string",
                                    "null",
                                    "boolean"
                                ]
                            },
                            "uomLabel": {
                                "type": "string"
                            }
                        }
                    }
                }
            }
        },
        "domainSet": {
            "title": "domainSet",
            "description": "The domainSet describes the *direct positions* of the coverage, i.e., the locations for which values are available.",
            "type": "object",
            "oneOf": [
                {
                    "required": [
                        "type",
                        "generalGrid"
                    ],
                    "properties": {
                        "type": {
                            "enum": [
                                "DomainSetType"
                            ]
                        },
                        "generalGrid": {
                            "title": "General Grid",
                            "description": "A general n-D grid is defined through a sequence of axes, each of which can be of a particular axis type.",
                            "type": "object",
                            "required": [
                                "type"
                            ],
                            "additionalProperties": false,
                            "properties": {
                                "type": {
                                    "enum": [
                                        "GeneralGridCoverageType"
                                    ]
                                },
                                "id": {
                                    "type": "string"
                                },
                                "srsName": {
                                    "type": "string",
                                    "format": "uri"
                                },
                                "axisLabels": {
                                    "type": "array",
                                    "items": {
                                        "type": "string"
                                    }
                                },
                                "axis": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "oneOf": [
                                            {
                                                "title": "Index Axis",
                                                "description": "An Index Axis is an axis with only integer positions allowed.",
                                                "required": [
                                                    "type",
                                                    "axisLabel",
                                                    "lowerBound",
                                                    "upperBound"
                                                ],
                                                "additionalProperties": false,
                                                "properties": {
                                                    "type": {
                                                        "enum": [
                                                            "IndexAxisType"
                                                        ]
                                                    },
                                                    "id": {
                                                        "type": "string"
                                                    },
                                                    "axisLabel": {
                                                        "type": "string"
                                                    },
                                                    "lowerBound": {
                                                        "type": "number"
                                                    },
                                                    "upperBound": {
                                                        "type": "number"
                                                    }
                                                }
                                            },
                                            {
                                                "title": "Regular Axis",
                                                "description": "A Regular Axis is an axis where all direct coordinates are at a common distance from its immediate neighbors.",
                                                "required": [
                                                    "type",
                                                    "axisLabel",
                                                    "lowerBound",
                                                    "upperBound",
                                                    "resolution",
                                                    "uomLabel"
                                                ],
                                                "additionalProperties": false,
                                                "properties": {
                                                    "type": {
                                                        "enum": [
                                                            "RegularAxisType"
                                                        ]
                                                    },
                                                    "id": {
                                                        "type": "string"
                                                    },
                                                    "axisLabel": {
                                                        "type": "string"
                                                    },
                                                    "lowerBound": {
                                                        "type": [
                                                            "number",
                                                            "string",
                                                            "null",
                                                            "boolean"
                                                        ]
                                                    },
                                                    "upperBound": {
                                                        "type": [
                                                            "number",
                                                            "string",
                                                            "null",
                                                            "boolean"
                                                        ]
                                                    },
                                                    "uomLabel": {
                                                        "type": "string"
                                                    },
                                                    "resolution": {
                                                        "type": "number"
                                                    }
                                                }
                                            },
                                            {
                                                "title": "Irregular Axis",
                                                "description": "An irregular axis enumerates all possible direct position coordinates.",
                                                "required": [
                                                    "type",
                                                    "axisLabel",
                                                    "uomLabel",
                                                    "coordinate"
                                                ],
                                                "additionalProperties": false,
                                                "properties": {
                                                    "type": {
                                                        "enum": [
                                                            "IrregularAxisType"
                                                        ]
                                                    },
                                                    "id": {
                                                        "type": "string"
                                                    },
                                                    "axisLabel": {
                                                        "type": "string"
                                                    },
                                                    "uomLabel": {
                                                        "type": "string"
                                                    },
                                                    "coordinate": {
                                                        "type": "array",
                                                        "items": {
                                                            "type": [
                                                                "number",
                                                                "string",
                                                                "boolean"
                                                            ]
                                                        }
                                                    }
                                                }
                                            }
                                        ]
                                    }
                                },
                                "displacement": {
                                    "title": "Displacement",
                                    "description": "A Displacement is a warped axis nest where points on the grid all have their individual direct position coordinates. The sequenceRule element describes linearization order.",
                                    "type": "object",
                                    "oneOf": [
                                        {
                                            "required": [
                                                "type",
                                                "axisLabels",
                                                "uomLabels",
                                                "coordinates"
                                            ],
                                            "properties": {
                                                "type": {
                                                    "enum": [
                                                        "DisplacementAxisNestType"
                                                    ]
                                                },
                                                "id": {
                                                    "type": "string"
                                                },
                                                "axisLabel": {
                                                    "type": "string"
                                                },
                                                "srsName": {
                                                    "type": "string",
                                                    "format": "uri"
                                                },
                                                "axisLabels": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string"
                                                    }
                                                },
                                                "uomLabels": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string"
                                                    }
                                                },
                                                "coordinates": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "array",
                                                        "items": {
                                                            "type": [
                                                                "number",
                                                                "string",
                                                                "boolean"
                                                            ]
                                                        }
                                                    }
                                                }
                                            }
                                        },
                                        {
                                            "required": [
                                                "type",
                                                "axisLabels",
                                                "uomLabels",
                                                "coordinatesRef"
                                            ],
                                            "properties": {
                                                "type": {
                                                    "enum": [
                                                        "DisplacementAxisNestTypeRef"
                                                    ]
                                                },
                                                "id": {
                                                    "type": "string"
                                                },
                                                "axisLabel": {
                                                    "type": "string"
                                                },
                                                "srsName": {
                                                    "type": "string",
                                                    "format": "uri"
                                                },
                                                "axisLabels": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string"
                                                    }
                                                },
                                                "uomLabels": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string"
                                                    }
                                                },
                                                "coordinatesRef": {
                                                    "type": "string",
                                                    "format": "uri"
                                                }
                                            }
                                        }
                                    ]
                                },
                                "model": {
                                    "title": "Sensor model",
                                    "description": "A Transformation By Sensor Model is a transformation definition which is given by a SensorML 2.0 transformation specification.",
                                    "type": "object",
                                    "required": [
                                        "type",
                                        "sensorModelRef"
                                    ],
                                    "properties": {
                                        "type": {
                                            "enum": [
                                                "TransformationBySensorModelType"
                                            ]
                                        },
                                        "id": {
                                            "type": "string"
                                        },
                                        "axisLabels": {
                                            "type": "array",
                                            "items": {
                                                "type": "string"
                                            }
                                        },
                                        "uomLabels": {
                                            "type": "array",
                                            "items": {
                                                "type": "string"
                                            }
                                        },
                                        "sensorModelRef": {
                                            "type": "string",
                                            "format": "uri"
                                        },
                                        "sensorInstanceRef": {
                                            "type": "string",
                                            "format": "uri"
                                        }
                                    }
                                },
                                "gridLimits": {
                                    "title": "Grid limits",
                                    "description": "This is the boundary of the array underlying the grid, given by its diagonal corner points in integer _60_3D. The grid limits can be omitted in case all axes are of type index axis, because then it repeats the grid information in a redundant way. The purpose of the axisLabels attribute, which lists the axis labels of all axisExtent elements in proper sequence, is to enforce axis sequence also in XML systems which do not preserve document order.",
                                    "type": "object",
                                    "required": [
                                        "type"
                                    ],
                                    "properties": {
                                        "indexAxis": {
                                            "title": "Index Axis",
                                            "description": "An Index Axis is an axis with only integer positions allowed.",
                                            "type": "object",
                                            "required": [
                                                "type",
                                                "lowerBound",
                                                "upperBound"
                                            ],
                                            "additionalProperties": false,
                                            "properties": {
                                                "type": {
                                                    "enum": [
                                                        "IndexAxisType"
                                                    ]
                                                },
                                                "id": {
                                                    "type": "string"
                                                },
                                                "axisLabel": {
                                                    "type": "string"
                                                },
                                                "lowerBound": {
                                                    "type": "number"
                                                },
                                                "upperBound": {
                                                    "type": "number"
                                                }
                                            }
                                        },
                                        "srsName": {
                                            "type": "string",
                                            "format": "uri"
                                        },
                                        "axisLabels": {
                                            "type": "array",
                                            "items": {
                                                "type": "string"
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
                {
                    "required": [
                        "type",
                        "directMultiPoint"
                    ],
                    "properties": {
                        "type": {
                            "enum": [
                                "DomainSetType"
                            ]
                        },
                        "directMultiPoint": {
                            "oneOf": [
                                {
                                    "required": [
                                        "type",
                                        "coordinates"
                                    ],
                                    "properties": {
                                        "type": {
                                            "enum": [
                                                "DirectMultiPointType"
                                            ]
                                        },
                                        "coordinates": {
                                            "type": "array",
                                            "items": {
                                                "type": "array",
                                                "items": {
                                                    "type": [
                                                        "number",
                                                        "string",
                                                        "boolean"
                                                    ]
                                                }
                                            }
                                        }
                                    }
                                },
                                {
                                    "required": [
                                        "type",
                                        "coordinatesRef"
                                    ],
                                    "properties": {
                                        "type": {
                                            "enum": [
                                                "DirectMultiPointTypeRef"
                                            ]
                                        },
                                        "coordinatesRef": {
                                            "type": "string",
                                            "format": "uri"
                                        }
                                    }
                                }
                            ]
                        }
                    }
                },
                {
                    "required": [
                        "type",
                        "fileReference"
                    ],
                    "properties": {
                        "type": {
                            "enum": [
                                "DomainSetRefType"
                            ]
                        },
                        "id": {
                            "type": "string",
                            "format": "uri"
                        },
                        "fileReference": {
                            "type": "string",
                            "format": "uri"
                        }
                    }
                }
            ]
        },
        "rangeSet": {
            "title": "rangeSet",
            "description": "The rangeSet lists a value for each of the coverage's direct positions. Values resemble the *payload* information of some particular direct positions. Values can be composite (with a single nesting level, i.e.: composites always consist of atomics), or atomic (emulated through single-component composites) whereby the sequence, structure, and meaning of every value is defined through the rangeType. Values can be represented in-line or by reference to an external file which may have any suitable encoding.",
            "type": "object",
            "oneOf": [
                {
                    "required": [
                        "type",
                        "dataBlock"
                    ],
                    "properties": {
                        "type": {
                            "enum": [
                                "RangeSetType"
                            ]
                        },
                        "dataBlock": {
                            "title": "dataBlock",
                            "description": "Data block objects",
                            "type": "object",
                            "required": [
                                "type",
                                "values"
                            ],
                            "properties": {
                                "type": {
                                    "enum": [
                                        "VDataBlockType",
                                        "CVDataBlockType"
                                    ]
                                },
                                "values": {
                                    "type": "array",
                                    "items": {
                                        "type": [
                                            "number",
                                            "string",
                                            "null",
                                            "boolean"
                                        ]
                                    }
                                }
                            }
                        }
                    }
                },
                {
                    "required": [
                        "type",
                        "fileReference"
                    ],
                    "properties": {
                        "type": {
                            "enum": [
                                "RangeSetRefType"
                            ]
                        },
                        "fileReference": {
                            "type": "array",
                            "items": {
                                "type": "string",
                                "format": "uri"
                            }
                        }
                    }
                }
            ]
        },
        "partitionSet": {
            "title": "Partitioning Set",
            "description": "A partition describes how a coverage (*sub-coverage*) referenced is located within referencing coverage (*super-coverage*). The sub-coverage can be represented by referencing a coverage id or a URL pointing to a coverage.  Such sub-coverages referenced may be grouped into the super-coverage document, or reside remote, or mixed. As an additional alternative, single range values can be indicated verbatimg, together with their direct position. All values must share an identical structure and conform to the rangeType definition.",
            "type": "object",
            "required": [
                "type"
            ],
            "properties": {
                "type": {
                    "enum": [
                        "PartitionSetType"
                    ]
                },
                "partition": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "oneOf": [
                            {
                                "required": [
                                    "type",
                                    "coverageRef"
                                ],
                                "properties": {
                                    "id": {
                                        "type": "string"
                                    },
                                    "type": {
                                        "enum": [
                                            "PartitionRefType"
                                        ]
                                    },
                                    "envelope": {
                                        "$ref": "#/definitions/envelope"
                                    },
                                    "coverageRef": {
                                        "type": "string",
                                        "format": "uri"
                                    }
                                }
                            },
                            {
                                "required": [
                                    "type",
                                    "coverage"
                                ],
                                "properties": {
                                    "id": {
                                        "type": "string"
                                    },
