                        "items": {
                            "type": "integer",
                            "exclusiveMinimum": 0
                        }
                    },
                    "MediumName": {
                        "type": "string",
                        "minLength": 1,
                        "description": "The unique name of the medium."
                    },
                    "Id": {
                        "description": "Identifier for this volume. This identifier should be unique amongst all other volumes.",
