{
    "id": "https://raw.githubusercontent.com/rolfvreijdenberger/jsend-json-schema/master/jsend-extend-fail-error-json-schema.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "jsend-extend-fail-error json schema",
    "description": "This is a json-schema that extends the jsend format for json responses for applications. It provides structured information about the 'status':'fail|error' reason(s) by specifying the structure of the 'data' key. Since the returned data for 'status':'success' depends on the API, the JSend spec is enough. The  returned data for 'status':'fail|error' should be in a format that is consumable by API consumers in a generic way. The JSend specification leaves this too open for interpretation. To provide a uniform way of consuming data for failures and errors, this schema defines an array of objects in the 'data' key. Each item in that array has at least the key 'message' with a human readable description of the failure. For an error, this will most likely be a single object specifying the error. In case it is possible to map it to an input field, an optional 'field' key can be used with a string representation of the map to the field. Even input in complex datastructures can be mapped this way. see https://labs.omniti.com/labs/jsend/wiki",
    "type": "object",
    "oneOf": [
        {
            "$ref": "#/definitions/success"
        },
        {
            "$ref": "#/definitions/fail"
        },
        {
            "$ref": "#/definitions/error"
        }
    ],
    "definitions": {
        "success": {
            "description": "All went well, and (usually) some data was returned.",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^success$",
                    "description": "the status for a succesful handling"
                },
                "data": {
                    "description": "Acts as the wrapper for any data returned by the API call. If the call returns no data (as in the last example), data should be set to null.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "fail": {
            "description": "There was a problem with the data submitted, or some pre-condition of the API call wasn't satisfied. this is a '400' http status type error (recoverable by client)",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^fail$",
                    "description": "the status for a failure handling"
                },
                "data": {
                    "description": "provides the wrapper for the details of why the request failed.",
                    "$ref": "#/definitions/data-fail-error"
                }
            }
        },
        "error": {
            "description": "An error occurred in processing the request, i.e. an exception was thrown. this is a '500' http status type error (unrecoverable by client)",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^error$",
                    "description": "the status for a failure handling"
                },
                "data": {
                    "description": "provides the wrapper for the details of why the request failed.",
                    "$ref": "#/definitions/data-fail-error"
                }
            }
        },
        "code": {
            "description": "A numeric code providing info about a failure or error in a result, if applicable",
            "type": [
                "string",
                "integer"
            ]
        },
        "data-fail-error": {
            "description": "a container for information about failures or errors",
            "type": [
                "array"
            ],
            "minItems": 0,
            "items": {
                "$ref": "#/definitions/data-fail-error-item"
            }
        },
        "data-fail-error-item": {
            "description": "an object that contains fields related to a failure",
            "type": "object",
            "required": [
                "message"
            ],
            "properties": {
                "message": {
                    "description": "a human readable failure or error message",
                    "$ref": "#/definitions/message"
                },
                "code": {
                    "description": "an optional numeric code, could be used for translations (incl gettext .po strings)",
                    "$ref": "#/definitions/code"
                },
                "field": {
                    "description": "an optional string representation that maps to input. POST keys, a query parameter, a header key etc. For complex datastructures you could use different solutions like a dot seperated tree representation, an xpath expression etc.",
                    "type": "string"
                }
            }
        },
        "data": {
            "description": "a generic container for data returned for success, fail or error",
            "type": [
                "string",
                "null",
                "array",
                "object",
                "integer",
                "boolean"
            ]
        },
        "message": {
            "description": "A meaningful, end-user-readable (or at the least log-worthy) message, explaining what happened.",
            "type": "string"
        }
    }
}

{
  "title": "A JSON Schema for x-ms-examples extension in Swagger 2.0 API.",
  "id": "https://raw.githubusercontent.com/Azure/autorest/master/schema/example-schema.json#",
  "$schema": "http://json-schema.org/draft-04/schema#",
  "type": "object",
  "required": [
    "parameters",
    "responses"
  ],
  "description": "Describes the format of an example defined using the x-ms-examples extension.",
  "additionalProperties": false,
  "properties": {
    "operationId": {
      "description": "The operationId in the swagger specification for which the example is being provided.",
      "type": "string"
    },
    "title": {
      "description": "The title in the swagger spec that uniquely identifies the swagger spec.",
      "type": "string"
    },
    "description": {
      "description": "A brief explanation about the current scenario.",
      "type": "string"
    },
    "parameters": {
      "$ref": "#/definitions/xmsParametersExample"
    },
    "responses": {
      "type": "object",
      "description": "A dictionary of {possible HTTP status codes (as the dictionary key)} that can be received from that operation and {examples (as the dictionary value)} of response {body} and {headers (for long running operations)}.",
      "minProperties": 1,
      "additionalProperties": false,
      "patternProperties": {
        "^([0-9]{3})$|^(default)$": {
          "$ref": "#/definitions/xmsResponseExample"
        }
      }
    }
  },
  "definitions": {
    "xmsParametersExample": {
      "type": "object",
      "description": "A dictionary of parameter names and their sample values for a particular operation. Commonly used parameters in Azure, like 'api-version', 'subscriptionId' and 'resourceGroupName' have been defined as optional properties for ease of use. Please add other parameters as applicable in your example.",
      "additionalProperties": true,
      "properties": {
        "api-version": {
          "type": "string",
          "description": "An example of the api-version used in the request.",
          "minLength": 3
        },
        "subcriptionId": {
          "type": "string",
          "description": "An example of the subcriptionId used in the request.",
          "minLength": 1
        },
        "resourceGroupName": {
          "type": "string",
          "description": "An example of the resourceGroupName used in the request.",
          "pattern": "^[-\\w\\._\\(\\)]+$",
          "minLength": 1,
          "maxLength": 90
        }
      }
    },
    "xmsResponseHeaderExample": {
      "type": "object",
      "description": "Examples of response headers. Common response headers like 'location', 'azure-asyncoperation', 'retry-after', etc. are defined as optional properties for ease of use. Please feel free to add other response headers as applicable in the example.",
      "properties": {
        "location": {
          "type": "string",
          "description": "An example of the location header sent by the server, if applicable in the example.",
          "minLength": 10,
          "pattern": "^(http|https)://.*"
        },
        "azure-asyncoperation": {
          "type": "string",
          "description": "An example of the azure-asyncoperation header sent by the server, if applicable in the example.",
          "minLength": 10,
          "pattern": "^(http|https)://.*"
        },
        "retry-after": {
          "type": "string",
          "description": "An example value of the retry-after header sent by the server, if applicable in the example.",
          "minLength": 1
        }
      },
      "additionalProperties": true
    },
    "xmsResponseExample": {
      "type": "object",
      "description": "Describes headers and body of an example HTTP response, in the context of the x-ms-examples extension.",
      "properties": {
        "headers": {
          "$ref": "#/definitions/xmsResponseHeaderExample"
        },
        "body": {
          "type": [
            "object",
            "number",
            "array",
            "integer",
            "string",
            "boolean",
            "null"
          ],
          "description": "Example of the response body if applicable for the operation. Don't specify the body if the server is not sending a response body. The outcome from `JSON.parse()`, needs to be described over here."
        }
      }
    }
  }
}

