{
    "id": "https://raw.githubusercontent.com/rolfvreijdenberger/jsend-json-schema/master/jsend-json-schema.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "jsend json schema",
    "description": "This is a json-schema for the jsend format for json responses for applications. see https://labs.omniti.com/labs/jsend/wiki",
    "type": "object",
    "oneOf": [
        {
            "$ref": "#/definitions/success"
        },
        {
            "$ref": "#/definitions/fail"
        },
        {
            "$ref": "#/definitions/error"
        }
    ],
    "definitions": {
        "success": {
            "description": "All went well, and (usually) some data was returned.",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^success$",
                    "description": "the status for a succesful handling"
                },
                "data": {
                    "description": "Acts as the wrapper for any data returned by the API call. If the call returns no data (as in the last example), data should be set to null.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "fail": {
            "description": "There was a problem with the data submitted, or some pre-condition of the API call wasn't satisfied",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^fail$",
                    "description": "the status for a failure handling"
                },
                "data": {
                    "description": "provides the wrapper for the details of why the request failed. If the reasons for failure correspond to POST values, the response object's keys SHOULD correspond to those POST values.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "error": {
            "description": "An error occurred in processing the request, i.e. an exception was thrown",
            "required": [
                "status",
                "message"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^error$",
                    "description": "the status for a error handling"
                },
                "message": {
                    "$ref": "#/definitions/message"
                },
                "code": {
                    "$ref": "#/definitions/code"
                },
                "data": {
                    "description": "A generic container for any other information about the error, i.e. the conditions that caused the error, stack traces, etc.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "data": {
            "description": "a generic container for data returned for success, fail or error",
            "type": [
                "string",
                "null",
                "array",
                "object",
                "integer",
                "boolean"
            ]
        },
        "code": {
            "description": "A numeric code corresponding to the error in an error result, if applicable",
            "type": [
                "string",
                "integer"
            ]
        },
        "message": {
            "description": "A meaningful, end-user-readable (or at the least log-worthy) message, explaining what went wrong in an error result.",
            "type": "string"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "descent-glovepie map",
    "description": "Describes the mappings for generating a GlovePIE script.",
    "type": "object",
    "properties": {
        "input": {
            "description": "Input prefix that is applied to all inputs.  For instance, if you set this to \"Sixaxis1\" and define a button mapping for \"Square\", then the generated script will use \"Sixaxis1.Square\".  This parameter is optional; if not specified, no prefix is applied to inputs.",
            "type": "string"
        },
        "alias": {
            "description": "Input aliases.  Allows arbitrary GlovePIE code to be used as an input.",
            "type": "object",
            "patternProperties": {
                "^[A-Za-z][A-Za-z0-9]*$": {
                    "description": "Alias for an input.",
                    "type": "string"
                }
            }
        },
        "shift": {
            "description": "List of inputs that can be used as shift buttons.",
            "type": "array",
            "items": {
                "type": "string",
                "pattern": "^:?[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z][A-Za-z0-9]*)*$"
            },
            "_uniqueItems": true
        },
        "axis": {
            "description": "Mappings for analog inputs to virtual joystick axes.  Each property name is an input, and each value is the output.",
            "type": "object",
            "patternProperties": {
                "^:?[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z][A-Za-z0-9]*)*$": {
                    "description": "Mapping of an analog input to an output.  The output may be inverted by putting a dash (-) at the beginning of the value.",
                    "type": "string",
                    "pattern": "^-?[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z][A-Za-z0-9]*)*$"
                }
            },
            "additionalProperties": false
        },
        "button": {
            "description": "Mappings for digital inputs to virtual joystick buttons, keyboard keys, or keyboard macros.  Each property name is an input.",
            "type": "object",
            "patternProperties": {
                "^:?[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z][A-Za-z0-9]*)*$": {
                    "oneOf": [
                        {
                            "description": "Simple mapping for this digital input.",
                            "$ref": "#/definitions/output"
                        },
                        {
                            "description": "Mappings for this digital input.  The property names are the shift button inputs, except \"normal\" which is the unshifted mapping.",
                            "type": "object",
                            "properties": {
                                "normal": {
                                    "description": "Normal, unshifted mapping for this digital input.",
                                    "$ref": "#/definitions/output"
                                }
                            },
                            "patternProperties": {
                                "^[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z][A-Za-z0-9]*)*$": {
                                    "description": "Shifted mapping for this digital input.  The property name is the shift button input.",
                                    "$ref": "#/definitions/output"
                                }
                            }
                        }
                    ]
                }
            },
            "additionalProperties": false
        },
        "throttle": {
            "description": "Special mapping for using two buttons as a joystick axis and optional virtual button that indicates when both buttons are pressed.",
            "type": "object",
            "properties": {
                "axis": {
                    "description": "Virtual joystick axis to use for the analog output.",
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9]*(\\.[A-Za-z][A-Za-z0-9]*)*$"
                },
                "button": {
                    "description": "Virtual joystick button to use for the digital output indicating when both buttons are pressed.",
                    "type": "string",
