                    "selection"
                ],
                "additionalProperties": false
            }
        },
        "tiebreak": {
            "description": "the candidate that should be chosen in the event of a tie",
            "type": "integer"
        },
        "results": {
            "description": "a record of what happened as the election was tabulated",
            "type": "object",
            "properties": {
                "winner": {
                    "description": "which candidate won the election",
                    "type": "integer"
                },
                "tabulation": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "candidate": {
                                "type": "integer"
                            },
                            "votes": {
                                "type": "integer"
                            }
                        },
                        "required": [
                            "candidate",
                            "votes"
                        ],
                        "additionalProperties": false
                    }
                }
            },
            "required": [
                "winner"
            ],
            "additionalProperties": false
        }
    },
    "additionalProperties": false,
    "dependencies": {
        "isTest": [
            "results",
            "tiebreak",
            "counts"
        ]
    }
}

